1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1],           [0, 1],
6	  [1, -1],  [1, 0],  [1, 1],
7	];
8	
9	const toKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	type NeighborTally = { cell: Cell; key: string; liveNeighborCount: number };
12	
13	function tallyLiveNeighborsForEachCandidate(liveCells: Cell[]): NeighborTally[] {
14	  const tallies = new Map<string, NeighborTally>();
15	  for (const [x, y] of liveCells) {
16	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
17	      const cell: Cell = [x + dx, y + dy];
18	      const key = toKey(cell);
19	      const tally = tallies.get(key) ?? { cell, key, liveNeighborCount: 0 };
20	      tally.liveNeighborCount += 1;
21	      tallies.set(key, tally);
22	    }
23	  }
24	  return [...tallies.values()];
25	}
26	
27	export function nextGeneration(liveCells: Cell[]): Cell[] {
28	  const aliveKeys = new Set(liveCells.map(toKey));
29	  const survives = ({ key, liveNeighborCount }: NeighborTally): boolean =>
30	    liveNeighborCount === 3 || (liveNeighborCount === 2 && aliveKeys.has(key));
31	  return tallyLiveNeighborsForEachCandidate(liveCells)
32	    .filter(survives)
33	    .map(({ cell }) => cell);
34	}
