type NeighborTally = { cell: Cell; liveNeighborCount: number };

function tallyLiveNeighborsByCell(liveCells: Cell[]): Map<string, NeighborTally> {
  const tallies = new Map<string, NeighborTally>();
  for (const [x, y] of liveCells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const cell: Cell = [x + dx, y + dy];
      const key = toKey(cell);
      const tally = tallies.get(key) ?? { cell, liveNeighborCount: 0 };
      tally.liveNeighborCount += 1;
      tallies.set(key, tally);
    }
  }
  return tallies;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const aliveKeys = new Set(liveCells.map(toKey));
  const survives = (key: string, liveNeighborCount: number): boolean =>
    liveNeighborCount === NEIGHBORS_TO_REPRODUCE ||
    (liveNeighborCount === NEIGHBORS_TO_SURVIVE && aliveKeys.has(key));
  return [...tallyLiveNeighborsByCell(liveCells)]
    .filter(([key, { liveNeighborCount }]) => survives(key, liveNeighborCount))
    .map(([, { cell }]) => cell);
}

